PREFIX tro: <http://example.org/ontology/transport#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?route ?platform ?platformName ?stopCode ?stopDescription ?stopIdentifier ?zone ?lat ?long
WHERE {
  ?trip a tro:Trip .
  ?trip tro:line ?line .
  ?line tro:fullTitle ?route .

  ?stopEvent a tro:StopEvent .
  ?stopEvent tro:journey ?trip .
  ?stopEvent tro:station ?stop .

  ?stop a tro:Stop .
  ?stop foaf:name ?platformName .
  ?stop tro:code ?stopCode .
  OPTIONAL { ?stop dcterms:description ?stopDescription . }
  OPTIONAL { ?stop dcterms:identifier ?stopIdentifier . }
  OPTIONAL { ?stop tro:zone ?zone . }
  OPTIONAL { ?stop geo:lat ?lat . }
  OPTIONAL { ?stop geo:long ?long . }

  BIND(CONCAT(?platformName, " (", ?stopCode, ")") AS ?platform)
}
LIMIT 1000

