PREFIX bsbm: <http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/vocabulary/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?item ?price ?type
WHERE {
  {
    SELECT ?item ?price
    WHERE {
      ?item a bsbm:Offer .
      ?item bsbm:price ?priceStr .
      BIND(xsd:decimal(?priceStr) AS ?price)
    }
    ORDER BY ?price
    LIMIT 5
    BIND('cheapest' AS ?type)
  }
  UNION
  {
    SELECT ?item ?price
    WHERE {
      ?item a bsbm:Offer .
      ?item bsbm:price ?priceStr .
      BIND(xsd:decimal(?priceStr) AS ?price)
    }
    ORDER BY DESC(?price)
    LIMIT 5
    BIND('costliest' AS ?type)
  }
}
ORDER BY ?type ?price

