deepseek_syn/SYN11_agentic_grep_4020dba7.final_sparql:
PREFIX eno: <http://example.org/ontology/energy#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?deposit ?designation (SUM(?extracted) AS ?total_extracted)
WHERE {
  ?output eno:extractedCrude ?extracted ;
          eno:outputForDeposit ?deposit .
  ?deposit eno:designation ?designation .
}
GROUP BY ?deposit ?designation
HAVING (SUM(?extracted) > 50000000)

