PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?company ?companyName ?productionSite WHERE {
  ?company a eno:Company .
  ?company eno:designation ?companyName .
  ?company eno:isCurrentLicenceOperator "true" .

  {
    ?productionSite a eno:Deposit .
    ?productionSite eno:activeDepositOperator ?company .
  } UNION {
    ?productionSite a eno:DevelopmentBorehole .
    ?productionSite eno:drillingOperatorCompany ?company .
  }
}
ORDER BY ?companyName

