PREFIX oriont: <https://orienting.eu/oriont#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?activity ?activityLabel ?flow ?flowType
WHERE {
  ?activity a oriont:Activity .
  OPTIONAL { ?activity rdfs:label ?activityLabel . }

  {
