PREFIX eno: <http://example.org/ontology/energy#>
PREFIX oriont: <https://orienting.eu/oriont#>
PREFIX oriont-ext: <https://orienting.eu/oriont-ext#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?emission ?label ?value ?unit
WHERE {
  {
    # Emissions from energy dataset (extracted gas)
    ?emission a eno:AnnualDepositOutput ;
              eno:extractedGas ?value .
    BIND("cubic meters" AS ?unit)
    BIND("Annual gas extraction" AS ?label)
  }
  UNION
  {
    # Emissions from LCA dataset (environmental flows)
    ?emission a oriont:Flow ;
              oriont-ext:hasFlowName ?label ;
              oriont-ext:hasMeasureValue ?value .
    FILTER(CONTAINS(LCASE(?label), "emission") || CONTAINS(LCASE(?label), "co2") || CONTAINS(LCASE(?label), "greenhouse") || CONTAINS(LCASE(?label), "pollutant"))
    BIND("kg" AS ?unit)
  }
  UNION
  {
    # Impact categories related to emissions
    ?emission a oriont:ImpactCategory ;
              rdfs:label ?label .
    FILTER(CONTAINS(LCASE(?label), "climate") || CONTAINS(LCASE(?label), "global warming") || CONTAINS(LCASE(?label), "emission") || CONTAINS(LCASE(?label), "air"))
    BIND(0 AS ?value)
    BIND("" AS ?unit)
  }
}
ORDER BY DESC(?value)
LIMIT 50

